#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

struct Report { std::vector<int> samples; };
int solve(int a, int b) { Report original{{a, b}}; Report copy = original; copy.samples[0] = b; return original.samples[0] + copy.samples[0]; }
